using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class RealityCollisionLandmarks:MonoBehaviour
{
private void Start(){BuildFrontRelics();BuildObjectiveHalos();BuildBaseCrowns();}
private void BuildFrontRelics(){for(int i=-2;i<=2;i++){float z=i*13f;BuildSplitRelic(z,i);}}
private void BuildSplitRelic(float z,int index){float yaw=index*17f;float side=3.8f;Create("DF_ZeroRelicHalf",PrimitiveType.Cube,new Vector3(-side,1.35f,z),new Vector3(.5f,2.7f,1.05f),StylizedArtDirection.ZeroDark,new Vector3(12,25+yaw,23));Create("DF_ZeroRelicEdge",PrimitiveType.Cube,new Vector3(-side+.48f,1.65f,z+.2f),new Vector3(.09f,2.05f,.72f),StylizedArtDirection.ZeroEnergy,new Vector3(12,25+yaw,23),true);Create("DF_LumenRelicHalf",PrimitiveType.Cube,new Vector3(side,1.35f,z),new Vector3(.5f,2.7f,1.05f),StylizedArtDirection.LumenDark,new Vector3(-8,-25-yaw,-12));Create("DF_LumenRelicEdge",PrimitiveType.Cube,new Vector3(side-.48f,1.65f,z-.2f),new Vector3(.09f,2.05f,.72f),StylizedArtDirection.LumenEnergy,new Vector3(-8,-25-yaw,-12),true);Color bridge=index%2==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;Create("DF_CollisionBridge",PrimitiveType.Cube,new Vector3(0,2.55f,z),new Vector3(5.8f,.08f,.12f),bridge,new Vector3(0,index*7f,0),true);}
private void BuildObjectiveHalos(){BuildHalo(new Vector3(0,.2f,-27),-1);BuildHalo(new Vector3(0,.2f,27),1);}
private void BuildHalo(Vector3 center,int direction){for(int i=0;i<10;i++){float a=i*36f*Mathf.Deg2Rad;Vector3 p=center+new Vector3(Mathf.Cos(a)*5.2f,.18f+((i%2)*.22f),Mathf.Sin(a)*5.2f);Color c=i%2==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;Create("DF_ObjectiveFractureHalo",PrimitiveType.Cube,p,new Vector3(.16f,.12f,1.15f),c,new Vector3(0,-i*36f+90f,0),i%3==0);}Create("DF_ObjectiveAxis",PrimitiveType.Cube,center+new Vector3(0,2.6f,0),new Vector3(.18f,5.2f,.18f),direction<0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy,new Vector3(0,45,0),true);}
private void BuildBaseCrowns(){BuildBaseCrown(-35f,true);BuildBaseCrown(35f,false);}
private void BuildBaseCrown(float x,bool zero){Color dark=zero?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;Color energy=zero?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;for(int i=0;i<6;i++){float z=(i-2.5f)*1.45f;float h=3.2f+Mathf.Abs(2.5f-i)*.7f;float tilt=zero?(i-2.5f)*9f:0f;Create(zero?"DF_ZeroBaseCrown":"DF_LumenBaseCrown",PrimitiveType.Cube,new Vector3(x,1.1f+h*.25f,z),new Vector3(.45f,h,.45f),dark,new Vector3(0,zero?18f:45f,tilt));float signalOffset=zero?.48f:-.48f;Create("DF_BaseCrownSignal",PrimitiveType.Cube,new Vector3(x+signalOffset,2.1f+h*.25f,z),new Vector3(.09f,h*.52f,.09f),energy,new Vector3(0,zero?18f:45f,tilt),true);}}
private void Create(string name,PrimitiveType type,Vector3 position,Vector3 scale,Color color,Vector3 rotation,bool pulse=false){GameObject g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(transform,false);g.transform.position=position;g.transform.localScale=scale;g.transform.rotation=Quaternion.Euler(rotation);Collider c=g.GetComponent<Collider>();if(c!=null){c.enabled=false;Object.Destroy(c);}Renderer r=g.GetComponent<Renderer>();if(r!=null)RuntimeMaterialPalette.Tint(gameObject,r,color);if(pulse)g.AddComponent<ArenaLightPulse>();}
}
}
